import random
from collections import Counter

def task_func(strings: list) -> dict:
    pattern = "pattern"
    per_string_counts = {}

    for idx, item in enumerate(strings):
        text = item if isinstance(item, str) else str(item)
        per_string_counts[idx] = text.count(pattern)

    return {
        "pattern": pattern,
        "per_string": per_string_counts,
        "total": sum(per_string_counts.values()),
        "distribution": dict(Counter(per_string_counts.values())),
    }
